from contextlib import contextmanager

@contextmanager
def timer(label):
    start = time.perf_counter()
    yield
    end = time.perf_counter()
    print(label + ':', end - start)

def process_data(data):
    with timer('Elapsed'):
        return (x * x for x in data if x > 0)

data = [1, -2, 3, -4, 5]
print(list(process_data(data)))

